//! The seeded Material Design 3 colour scheme: every colour role (primary,
//! secondary, tertiary and error families, the surface tonal levels from
//! surface-container-lowest to -highest, outline and outline-variant, the
//! inverse roles) generated by Material Color Utilities' dynamic scheme from
//! the seed, light and dark; harmonized success and warning custom colours;
//! and the pure black variant of the dark scheme.

use material_colors::blend::harmonize;
use material_colors::color::Rgb;
use material_colors::dynamic_color::{DynamicScheme, MaterialDynamicColors};
use material_colors::hct::Hct;
use material_colors::palette::TonalPalette;
use material_colors::scheme::variant::{SchemeContent, SchemeFidelity, SchemeMonochrome, SchemeTonalSpot};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ColorStyle {
    Vivid,
    Tinted,
    Soft,
    Monochrome,
}

impl ColorStyle {
    pub fn of(name: &str) -> Self {
        match name.to_ascii_lowercase().as_str() {
            "tinted" => Self::Tinted,
            "soft" => Self::Soft,
            "monochrome" => Self::Monochrome,
            _ => Self::Vivid,
        }
    }
}

/// ARGB colours of one scheme, named after BoxScheme.
#[derive(Clone, Copy, Debug, Default)]
pub struct BoxScheme {
    pub dark: bool,
    pub primary: u32,
    pub on_primary: u32,
    pub primary_container: u32,
    pub on_primary_container: u32,
    pub secondary: u32,
    pub on_secondary: u32,
    pub secondary_container: u32,
    pub on_secondary_container: u32,
    pub tertiary: u32,
    pub on_tertiary: u32,
    pub tertiary_container: u32,
    pub on_tertiary_container: u32,
    pub error: u32,
    pub on_error: u32,
    pub error_container: u32,
    pub on_error_container: u32,
    pub outline: u32,
    pub outline_variant: u32,
    pub on_surface: u32,
    pub on_surface_variant: u32,
    pub inverse_surface: u32,
    pub on_inverse_surface: u32,
    pub inverse_primary: u32,
    pub scrim: u32,
    pub shadow: u32,
    pub surface: u32,
    pub surface_bright: u32,
    pub surface_dim: u32,
    pub surface_container_lowest: u32,
    pub surface_container_low: u32,
    pub surface_container: u32,
    pub surface_container_high: u32,
    pub surface_container_highest: u32,
    pub success: u32,
    pub success_container: u32,
    pub on_success_container: u32,
    pub warning: u32,
    pub warning_container: u32,
    pub on_warning_container: u32,
}

fn argb(rgb: Rgb) -> u32 {
    0xff00_0000 | (rgb.red as u32) << 16 | (rgb.green as u32) << 8 | rgb.blue as u32
}

fn rgb(argb: u32) -> Rgb {
    Rgb { red: (argb >> 16) as u8, green: (argb >> 8) as u8, blue: argb as u8 }
}

pub fn hct_color(hue: f64, chroma: f64, tone: f64) -> u32 {
    hct_argb(Hct::from(hue, chroma, tone))
}

fn hct_argb(hct: Hct) -> u32 {
    argb(Rgb::from(hct))
}

fn tone_of(argb_value: u32) -> f64 {
    Hct::new(rgb(argb_value)).get_tone()
}

/// The M3 dynamic scheme variant for a colour style (spec 2021, phone):
/// vivid keeps the seed's chroma (Fidelity), tinted lets the seed tint the
/// neutrals (Content), soft is the M3 default (TonalSpot).
fn dynamic_scheme(source: Hct, dark: bool, style: ColorStyle) -> DynamicScheme {
    match style {
        ColorStyle::Vivid => SchemeFidelity::new(source, dark, Some(0.0)).scheme,
        ColorStyle::Tinted => SchemeContent::new(source, dark, Some(0.0)).scheme,
        ColorStyle::Soft => SchemeTonalSpot::new(source, dark, Some(0.0)).scheme,
        ColorStyle::Monochrome => SchemeMonochrome::new(source, dark, Some(0.0)).scheme,
    }
}

/// An M3 custom colour (success, warning): the design colour harmonized
/// toward the seed, as role, container and on-container tones.
fn custom(design: u32, seed: u32, dark: bool) -> (u32, u32, u32) {
    let harmonized = Hct::new(harmonize(rgb(design), rgb(seed)));
    let palette = TonalPalette::from_hue_and_chroma(harmonized.get_hue(), harmonized.get_chroma().max(48.0));
    let tone = |light: i32, dark_tone: i32| argb(palette.tone(if dark { dark_tone } else { light }));
    (tone(40, 80), tone(90, 30), tone(10, 90))
}

/// Every M3 colour role of the seed's scheme, straight from Material Color
/// Utilities; only the success and warning custom colours are FK-box's.
pub fn seeded_color_scheme(seed_color: u32, dark: bool, style: ColorStyle) -> BoxScheme {
    let seed_color = seed_color | 0xff00_0000;
    let source = Hct::new(rgb(seed_color));
    let scheme = dynamic_scheme(source, dark, style);
    let m = |c: material_colors::dynamic_color::DynamicColor| argb(scheme.get_rgb(c));
    let (success, success_container, on_success_container) = custom(0xFF2E7D32, seed_color, dark);
    let (warning, warning_container, on_warning_container) = custom(0xFFEF6C00, seed_color, dark);
    BoxScheme {
        dark,
        primary: m(MaterialDynamicColors::primary()),
        on_primary: m(MaterialDynamicColors::on_primary()),
        primary_container: m(MaterialDynamicColors::primary_container()),
        on_primary_container: m(MaterialDynamicColors::on_primary_container()),
        secondary: m(MaterialDynamicColors::secondary()),
        on_secondary: m(MaterialDynamicColors::on_secondary()),
        secondary_container: m(MaterialDynamicColors::secondary_container()),
        on_secondary_container: m(MaterialDynamicColors::on_secondary_container()),
        tertiary: m(MaterialDynamicColors::tertiary()),
        on_tertiary: m(MaterialDynamicColors::on_tertiary()),
        tertiary_container: m(MaterialDynamicColors::tertiary_container()),
        on_tertiary_container: m(MaterialDynamicColors::on_tertiary_container()),
        error: m(MaterialDynamicColors::error()),
        on_error: m(MaterialDynamicColors::on_error()),
        error_container: m(MaterialDynamicColors::error_container()),
        on_error_container: m(MaterialDynamicColors::on_error_container()),
        outline: m(MaterialDynamicColors::outline()),
        outline_variant: m(MaterialDynamicColors::outline_variant()),
        on_surface: m(MaterialDynamicColors::on_surface()),
        on_surface_variant: m(MaterialDynamicColors::on_surface_variant()),
        inverse_surface: m(MaterialDynamicColors::inverse_surface()),
        on_inverse_surface: m(MaterialDynamicColors::inverse_on_surface()),
        inverse_primary: m(MaterialDynamicColors::inverse_primary()),
        scrim: m(MaterialDynamicColors::scrim()),
        shadow: m(MaterialDynamicColors::shadow()),
        surface: m(MaterialDynamicColors::surface()),
        surface_bright: m(MaterialDynamicColors::surface_bright()),
        surface_dim: m(MaterialDynamicColors::surface_dim()),
        surface_container_lowest: m(MaterialDynamicColors::surface_container_lowest()),
        surface_container_low: m(MaterialDynamicColors::surface_container_low()),
        surface_container: m(MaterialDynamicColors::surface_container()),
        surface_container_high: m(MaterialDynamicColors::surface_container_high()),
        surface_container_highest: m(MaterialDynamicColors::surface_container_highest()),
        success,
        success_container,
        on_success_container,
        warning,
        warning_container,
        on_warning_container,
    }
}

fn shift_tone(color: u32, delta: f64) -> u32 {
    let hct = Hct::new(rgb(color));
    hct_argb(Hct::from(hct.get_hue(), hct.get_chroma(), (hct.get_tone() + delta).clamp(0.0, 100.0)))
}

impl BoxScheme {
    /// toPureBlack: black page surfaces; the containers drop by the surface tone.
    pub fn to_pure_black(mut self, pure_black: bool) -> Self {
        if !pure_black || !self.dark {
            return self;
        }
        let shift = tone_of(self.surface);
        self.surface = 0xff00_0000;
        self.surface_dim = 0xff00_0000;
        self.surface_container_lowest = 0xff00_0000;
        self.surface_container_low = shift_tone(self.surface_container_low, -shift);
        self.surface_container = shift_tone(self.surface_container, -shift);
        self.surface_container_high = shift_tone(self.surface_container_high, -shift);
        self.surface_container_highest = shift_tone(self.surface_container_highest, -shift);
        self.surface_bright = shift_tone(self.surface_bright, -shift);
        self
    }
}

/// Relative luminance in 0..1, for picking a readable mark on a swatch.
pub fn luminance(argb_value: u32) -> f64 {
    let lin = |c: u32| {
        let v = (c & 0xff) as f64 / 255.0;
        if v <= 0.03928 {
            v / 12.92
        } else {
            ((v + 0.055) / 1.055).powf(2.4)
        }
    };
    0.2126 * lin(argb_value >> 16) + 0.7152 * lin(argb_value >> 8) + 0.0722 * lin(argb_value)
}

/// WCAG contrast ratio of two colours (the theme tests check role pairs with it).
#[cfg(test)]
pub fn contrast(a: u32, b: u32) -> f64 {
    let (la, lb) = (luminance(a), luminance(b));
    let (hi, lo) = if la > lb { (la, lb) } else { (lb, la) };
    (hi + 0.05) / (lo + 0.05)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn default_blue_keeps_its_hue() {
        let light = seeded_color_scheme(0xff007aff, false, ColorStyle::Vivid);
        let seed_hue = Hct::new(rgb(0xff007aff)).get_hue();
        assert!((Hct::new(rgb(light.primary)).get_hue() - seed_hue).abs() < 10.0);
        let dark = seeded_color_scheme(0xff007aff, true, ColorStyle::Vivid).to_pure_black(true);
        assert_eq!(dark.surface, 0xff000000);
        assert!(tone_of(dark.on_surface) > 85.0);
    }

    /// The on-roles stay readable on their roles (4.5:1 for text) in every
    /// style, light and dark, pure black included, for a spread of seeds.
    #[test]
    fn role_pairs_meet_contrast() {
        let seeds = [0xff007aff, 0xffe53935, 0xff43a047, 0xfffdd835, 0xff8e24aa, 0xff795548, 0xff9e9e9e];
        let styles = [ColorStyle::Vivid, ColorStyle::Tinted, ColorStyle::Soft, ColorStyle::Monochrome];
        for seed in seeds {
            for style in styles {
                for dark in [false, true] {
                    for pure in [false, true] {
                        let s = seeded_color_scheme(seed, dark, style).to_pure_black(pure);
                        let pairs = [
                            ("primary", s.on_primary, s.primary),
                            ("primary-container", s.on_primary_container, s.primary_container),
                            ("secondary-container", s.on_secondary_container, s.secondary_container),
                            ("tertiary-container", s.on_tertiary_container, s.tertiary_container),
                            ("error", s.on_error, s.error),
                            ("error-container", s.on_error_container, s.error_container),
                            ("surface", s.on_surface, s.surface),
                            ("surface-variant", s.on_surface_variant, s.surface_container_highest),
                            // The opaque floating surfaces: the navigation bar,
                            // the scrolled top app bar and menus (container),
                            // dialogs and the foot bar (container-high).
                            ("surface-container", s.on_surface_variant, s.surface_container),
                            ("surface-container-high", s.on_surface_variant, s.surface_container_high),
                            ("inverse", s.on_inverse_surface, s.inverse_surface),
                            ("success-container", s.on_success_container, s.success_container),
                            ("warning-container", s.on_warning_container, s.warning_container),
                        ];
                        for (name, fg, bg) in pairs {
                            let ratio = contrast(fg, bg);
                            assert!(ratio >= 4.5, "{name} {seed:08x} {style:?} dark={dark} pure={pure}: {ratio:.2}");
                        }
                        // Outlines are non-text graphics (3:1) on the page.
                        assert!(contrast(s.outline, s.surface) >= 3.0, "outline {seed:08x} {style:?} dark={dark}");
                    }
                }
            }
        }
    }
}
